        y=.2126729*rr+.7151522*gg+.072175*bb
        z=(.0193339*rr+.119192*gg+.9503041*bb)/1.08883
        def f(t):return t**(1/3) if t>.008856 else 7.787*t+16/116
        fx,fy,fz=f(x),f(y),f(z)
        return (116*fy-16,500*(fx-fy),200*(fy-fz))
