    old=old.ansi();new=new.ansi()
    if old==new:return ''
    reset=(old.fg is not None and new.fg is None or old.bg is not None and new.bg is None or any(a not in new.attrs for a in old.attrs))
    if reset:return RESET+new.code()
    attrs=tuple(a for a in new.attrs if a not in old.attrs)
    return Style(new.fg if new.fg!=old.fg else None,new.bg if new.bg!=old.bg else None,attrs).code()

