    with open(os.path.join(ROOT,'data',name),encoding='utf8') as f:return f.read()

def main():
    try:
        cli,paths=parse_cli(sys.argv[1:])
        if cli.get('version'):sys.stdout.write('delta 0.18.2\n');return
        if cli.get('help'):
            sys.stdout.write(read_resource('short-help.txt' if cli['help']=='short' else 'help.txt'));return
        c=Config(cli)
        if c['show-config']:sys.stdout.write(c.show());return
        if c['list-syntax-themes']:
            text=read_resource('syntax-themes.txt')
            if c['light']:text=''.join(l for l in text.splitlines(True) if l.startswith('light'))
            elif c['dark']:text=''.join(l for l in text.splitlines(True) if l.startswith('dark'))
            sys.stdout.write(text);return
        if c['list-languages']:sys.stdout.write(read_resource('languages.txt'));return
        if c['generate-completion']:
            shell=c['generate-completion'];p=os.path.join(ROOT,'etc','completion','completion.'+shell)
            if os.path.isfile(p):sys.stdout.write(open(p).read())
            return
        if c['show-themes']:
            return
        if c['show-colors']:
            show_colors(c);return
        if c['show-syntax-themes']:
            show_syntax_themes(c);return
        status=0
        if len(paths)>=2:
            args=['git','diff','--no-index','--color=always']
            if c['diff-args']:
                try:args+=shlex.split(c['diff-args'])
                except ValueError:args+=str(c['diff-args']).split()
            args+=paths[:2]
            p=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
            if p.stderr:
                for l in p.stderr.decode('utf8','replace').splitlines():sys.stderr.write('git diff: '+l+'\n')
            data=p.stdout.decode('utf8','replace');status=0 if p.returncode==0 else 1
        else:data=sys.stdin.buffer.read().decode('utf8','replace')
        output=Viewer(c).process(data)
        sys.stdout.write(output)
        if status:raise SystemExit(status)
    except (CliError,ValueError) as e:
        sys.stderr.write(str(e));raise SystemExit(2)
    except BrokenPipeError:
        try:sys.stdout.close()
        except BrokenPipeError:pass
        raise SystemExit(0)


